using System; using System.Windows.Forms; using Inventory.Contracts;
namespace Inventory.Client { internal sealed class AuditForm:Form { private readonly Func<IInventoryGateway> _factory; private readonly DateTimePicker _start=new DateTimePicker(); private readonly DateTimePicker _end=new DateTimePicker(); private readonly DataGridView _grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=true}; public AuditForm(Func<IInventoryGateway> factory){_factory=factory;Text="Bitácora";Width=800;Height=450;_start.Value=DateTime.Today.AddDays(-30);_end.Value=DateTime.Today;var btn=new Button{Text="Consultar",AutoSize=true};btn.Click+=(s,e)=>{try{_grid.DataSource=_factory().GetAuditLog(_start.Value,_end.Value);}catch(Exception ex){MessageBox.Show(ex.Message);}};var panel=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,Padding=new Padding(8)};panel.Controls.AddRange(new Control[]{_start,_end,btn});Controls.Add(_grid);Controls.Add(panel);} } }
